'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>BO.numeric(n)?new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n):'—';
const qty=n=>BO.numeric(n)?new Intl.NumberFormat('en-GB',{maximumFractionDigits:3}).format(n):'—';
const dateText=d=>BO.validDate(d)?new Date(d+'T12:00:00').toLocaleDateString('en-GB'):'Not confirmed';
const KEY='brick-olive-workbook-v1', CFG='brick-olive-github-v1', DRAFT='brick-olive-entry-v1', TOKEN='brick-olive-device-token-v1';
let state, initial, localMeta={sha:null,dirty:false}, repo=null, route='dashboard', query='', category='', statusFilter='', dateFilter='', page=1;
let entryRows=[], batch={date:BO.today(),supplier:'',location:'',receiptId:'',total:'',reference:''}, entryEditing=null, countDraft={}, timer, syncTimer, busy=false, bootError='';
const routes=[['dashboard','Dashboard'],['purchases','Purchases & expenses'],['stock','Stock'],['shopping','Shopping'],['items','Items'],['receipts','Receipts'],['report','Daily report'],['guide','Guide']];
function flash(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function badge(text){const good=['Recorded','In stock','Matched','Expense only'].includes(text);const bad=/duplicate|difference|future|target/i.test(text);return `<span class="badge ${good?'good':bad?'bad':''}">${esc(text)}</span>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">BRICK & OLIVE WORKBOOK</span><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function action(a,label,cls='',id=''){return `<button data-action="${a}" ${id?`data-id="${esc(id)}"`:''} class="${cls}">${label}</button>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">No matching records.</td></tr>`}</tbody></table></div>`;}
function metric(label,value,note){return `<div class="metric"><span class="metric-label">${label}</span><strong class="metric-value">${value}</strong><small>${note}</small></div>`;}
function options(values,selected='',blank='All categories'){return `<option value="">${blank}</option>`+[...new Set(values)].filter(Boolean).sort().map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');}
function cats(){return [...new Set([...BO.categories,...state.items.map(i=>i.category)])];}
function toolsBar(withStatus=false,withDate=false){return `<div class="toolbar"><input id="search" type="search" placeholder="Search items, suppliers or notes…" aria-label="Search records" value="${esc(query)}"><select id="category-filter" aria-label="Filter category">${options(cats(),category)}</select>${withStatus?`<select id="status-filter" aria-label="Filter entry status">${options(['Needs attention','Recorded'],statusFilter,'All statuses')}</select>`:''}${withDate?`<input id="date-filter" type="date" aria-label="Filter purchase date" value="${esc(dateFilter)}">${action('clear-filter','Clear filters','text-button')}`:''}<span class="result-count" id="result-count"></span></div>`;}
function match(r){return (!category||r.category===category)&&(!query||Object.values(r).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase())));}
function paginate(rows){const pages=Math.max(1,Math.ceil(rows.length/60));page=Math.min(page,pages);return {slice:rows.slice((page-1)*60,page*60),footer:`<div class="sheet-caption"><span>${rows.length} records · Page ${page} of ${pages}</span><div>${action('prev','Previous','text-button')}${action('next','Next','text-button')}</div></div>`};}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${title}</h2>${action('close','✕','text-button')}</div><div class="modal-body">${body}</div>`;$('#modal').showModal();}
function closeModal(){ $('#modal').close(); }
function fail(message){modal('Please check',`<p class="error">${esc(message)}</p><div class="modal-actions">${action('close','OK','primary')}</div>`);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({state,...localMeta}));return true;}catch(e){bootError='This browser could not save a recovery copy. Download a backup now.';updateStatus();flash(bootError);return false;}}
function changed(message='Saved'){state.updatedAt=new Date().toISOString();localMeta.dirty=true;persist();updateStatus();if(repo?.token){clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync(),1400);}if(message)flash(repo?.token?message+' · Saving to GitHub…':message+' · Local draft');}
function updateStatus(text){$('#save-status').textContent=text||(bootError?'Recovery unavailable':repo?.busy?'Saving to GitHub…':localMeta.dirty?'Local changes · not synced':repo?.sha?'Up to date with GitHub':'Preview · GitHub not connected');$('#save-status').classList.toggle('sync-error',!!bootError||localMeta.dirty);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function backup(){download(`brick-olive-${BO.today()}.backup.json`,JSON.stringify(state,null,2));flash('Backup downloaded.');}
function readDraft(){try{const d=JSON.parse(localStorage.getItem(DRAFT)||'null');if(d){entryRows=d.rows;batch=d.batch;entryEditing=d.editing||null;}}catch{}if(!entryRows.length)entryRows=[blankRow(),blankRow(),blankRow()];}
function saveEntryDraft(){try{localStorage.setItem(DRAFT,JSON.stringify({rows:entryRows,batch,editing:entryEditing}));}catch{flash('Entry draft could not be backed up locally. Keep this page open until saved.');}}
function blankRow(){return {date:batch.date,item:'',category:'',supplier:batch.supplier,quantityText:'',cost:'',location:batch.location,packs:1,packSize:null,receiptId:batch.receiptId,line:null,notes:''};}
function render(){if(!state)return;route=location.hash.slice(1)||'dashboard';if(![...routes.map(r=>r[0]),'data'].includes(route))route='dashboard';$('#nav').innerHTML=routes.map(([r,n])=>`<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${n}</a>`).join('');const views={dashboard,items,stock,purchases,shopping,receipts,report,guide,data:dataView};$('#main').innerHTML=views[route]();updateStatus();if(['items','stock','purchases','receipts'].includes(route))renderRows();}
function dashboard(){const m=BO.metrics(state,state.reportDate);const cat=cats().map(c=>({name:c,amount:BO.sum(m.ps.filter(p=>p.category===c&&p.date?.slice(0,7)===state.reportDate.slice(0,7)),p=>p.amount)})).filter(c=>c.amount>0).sort((a,b)=>b.amount-a.amount);const max=Math.max(1,...cat.map(c=>c.amount));const days=[];for(let i=13;i>=0;i--){const d=new Date(state.reportDate+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-i);const key=d.toISOString().slice(0,10);days.push({date:key,value:BO.sum(m.ps.filter(p=>p.date===key),p=>p.amount)});}const peak=Math.max(1,...days.map(d=>d.value));const attention=m.stocks.filter(s=>s.status==='Low stock'||s.bring>0).slice(0,6);
return heading('A clear view of your day.','Stock, buying needs and spending, calculated from your workbook.',`<label class="date-control">Summary date <input id="report-date" type="date" value="${state.reportDate}"></label>${action('go-purchases','+ Add purchases','primary')}`)+
`<div class="metrics">${metric('Stock value',money(m.value),'Counted, priced items only')}${metric('Spent this month',money(m.month),new Date(state.reportDate+'T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'}))}${metric('Shopping estimate',money(m.shopping),`${m.stocks.filter(s=>s.buy>0).length} products to buy`)}${metric('Products tracked',qty(state.items.length),`${m.low} low stock · ${m.uncounted} awaiting counts`)}</div>
${m.incomplete||m.uncounted?`<div class="notice"><span><strong>A few details need your attention.</strong> ${m.uncounted} products need physical counts; ${m.incomplete} purchase entries need confirmation. Spending includes entered costs.</span>${action('attention','Review purchases','text-button')}</div>`:''}
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Purchase spending</h2><span class="small">14 days ending ${dateText(state.reportDate)}</span></div><div class="panel-body"><div class="period-summary"><div><span>Selected day</span><strong>${money(m.day)}</strong></div><div><span>Week · Monday–Sunday</span><strong>${money(m.week)}</strong></div><div><span>All purchases</span><strong>${money(m.total)}</strong></div></div><div class="trend" role="img" aria-label="Purchase spending by day">${days.map(d=>`<div class="trend-col" title="${dateText(d.date)}: ${money(d.value)}"><div class="trend-bar" style="height:${Math.max(1,d.value/peak*105)}px"></div><span>${d.date.slice(8)}</span></div>`).join('')}</div><p class="chart-note">Purchase dates drive this chart. Undated entries remain in the all-purchases total.</p></div></section>
<section class="panel"><div class="panel-head"><h2>Spending by category</h2><span class="small">Selected month</span></div><div class="panel-body">${cat.length?cat.slice(0,7).map(c=>`<div class="bar-row"><div class="bar-label"><span>${esc(c.name)}</span><strong>${money(c.amount)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${c.amount/max*100}%"></div></div></div>`).join(''):'<p class="muted">No purchases in this month.</p>'}</div></section></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Restock & bring from home</h2>${action('go-shopping','Open shopping list','text-button')}</div>${attention.length?table(['Item','At shop','At home','Buy packs','Bring'],attention.map(s=>`<tr><td class="name">${esc(s.name)}</td><td>${qty(s.shop)} ${esc(s.unit)}</td><td>${qty(s.home)}</td><td>${qty(s.buy)}</td><td>${qty(s.bring)}</td></tr>`)):`<div class="empty"><h3>${m.uncounted?'Start with a stock count':'No restocking needed'}</h3><p>${m.uncounted?'Enter Shop and Home counts to calculate your shopping list.':'Your recorded stock is above the buying levels.'}</p>${action('go-stock','Open stock counts','primary')}</div>`}</section><section class="panel"><div class="panel-head"><h2>Workbook checks</h2><span class="small">Live calculations</span></div><div class="panel-body check-list"><div class="check-row"><span>Uncounted products</span><strong>${m.uncounted}</strong></div><div class="check-row"><span>Incomplete purchases</span><strong>${m.incomplete}</strong></div><div class="check-row"><span>Receipt checks to review</span><strong>${state.receipts.map(r=>BO.receipt(r,state,m.ps)).filter(r=>r.status!=='Matched').length}</strong></div><div class="check-row"><span>Counted but unpriced</span><strong>${m.stocks.filter(s=>s.status==='Add pack price').length}</strong></div></div></section></div>`;}
function items(){return heading('Your item catalogue.','Set up each product once. Its details fill automatically when you enter purchases.',action('add-item','+ Add item','primary'))+toolsBar()+`<div id="records"></div><p class="entry-help">Minimum and target quantities use the item’s unit. Blank values stay unknown; enter 0 when zero is correct.</p>`;}
function stock(){return heading('Stock at shop & home.','Enter end-of-day counts. Later-dated purchases are added automatically.',action('save-counts','Save counts','primary'))+`<div class="notice neutral"><span>Amber cells are editable. Count after the day’s purchases, usage and transfers. Purchases on the count date are already included.</span></div>`+toolsBar()+`<div id="records"></div><div class="foot-actions">${action('save-counts','Save counts','primary')}</div>`;}
function purchases(){return heading('Purchases & expenses.','Add receipt lines just like a spreadsheet. Saving updates your dashboard automatically.',action('import','Import Excel')+action('export','Export workbook'))+
`<section class="panel entry-section"><div class="panel-head"><h2>${entryEditing?'Edit purchase':'Quick entry'}</h2><span class="small">Tab between cells · Paste rows from Excel</span></div><div class="panel-body"><div class="batch-settings"><label>Receipt date<input type="date" data-batch="date" value="${esc(batch.date)}"></label><label>Supplier<input data-batch="supplier" value="${esc(batch.supplier)}" list="suppliers" placeholder="e.g. Aldi"></label><label>Kept at<select data-batch="location">${options(['Shop','Home'],batch.location,'Choose location')}</select></label><label>Receipt ID<input data-batch="receiptId" value="${esc(batch.receiptId)}" placeholder="e.g. R028"></label></div>
<div class="table-wrap"><table class="entry-grid"><thead><tr><th>#</th><th>Date</th><th>Item</th><th>Category</th><th>Supplier</th><th>Quantity</th><th>Cost (£)</th><th>Kept at</th><th></th></tr></thead><tbody id="entry-body">${entryRows.map(entryRow).join('')}</tbody></table></div><datalist id="item-names">${state.items.map(i=>`<option value="${esc(i.name)}">`).join('')}</datalist><datalist id="category-names">${cats().map(c=>`<option value="${esc(c)}">`).join('')}</datalist><datalist id="suppliers">${[...new Set([...state.items.map(i=>i.supplier),...state.purchases.map(p=>p.supplier)])].filter(Boolean).map(s=>`<option value="${esc(s)}">`).join('')}</datalist>
<p class="entry-help">Cost is the <strong>total paid for that row</strong>. Quantity can read “24 pack” or “5 kg”. Use <strong>Details</strong> for packs bought, units per pack, receipt line or notes. Unknown pack sizes stay flagged for confirmation.</p><div class="entry-actions"><div class="actions">${action('add-row','+ Add row')}${action('paste','Paste from Excel')}${action('clear-entry',entryEditing?'Cancel edit':'Clear entry','text-button')}</div><div class="totals-line">Total <span id="entry-total" class="total-figure">${money(entryTotal())}</span>${action('save-entries',entryEditing?'Save changes':'Save entries','primary')}</div></div><details><summary class="small">Receipt total & reference (optional)</summary><div class="batch-settings"><label>Printed receipt total (£)<input type="number" min="0" step="0.01" data-batch="total" value="${esc(batch.total)}"></label><label>Receipt reference<input data-batch="reference" value="${esc(batch.reference)}"></label></div><p class="small">A new receipt ID is registered when you save. Edit receipt details in Receipts. Receipt totals are reconciled against purchase lines, never added to spending twice.</p></details></div></section>
${toolsBar(true,true)}<div id="records"></div>`;}
function entryRow(r,i){return `<tr data-row="${i}"><td class="index">${i+1}</td>${[['date','date',''],['item','text','item-names'],['category','text','category-names'],['supplier','text','suppliers'],['quantityText','text',''],['cost','number','']].map(([k,t,l])=>`<td><input aria-label="Row ${i+1} ${k==='quantityText'?'quantity':k}" data-entry="${k}" type="${t}" ${t==='number'?'min="0" step="0.01"':''} ${l?`list="${l}"`:''} value="${esc(r[k])}" ${k==='item'?'placeholder="Choose or type an item"':''}></td>`).join('')}<td><select aria-label="Row ${i+1} location" data-entry="location">${options(['Shop','Home'],r.location,'Choose')}</select></td><td>${action('row-details','Details','text-button',String(i))}${action('remove-row','×','text-button',String(i))}</td></tr>`;}
function entryTotal(){return BO.sum(entryRows,r=>BO.num(r.cost));}
function renderEntry(){ $('#entry-body').innerHTML=entryRows.map(entryRow).join('');$('#entry-total').textContent=money(entryTotal());saveEntryDraft();}
function shopping(){const m=BO.metrics(state),list=m.stocks.filter(s=>s.buy>0||s.bring>0||s.extra>0);return heading('Your shopping list.','Automatic restocking, home transfers and extra requests.',action('request','+ Extra request','primary')+action('print','Print list'))+`<div class="metrics">${metric('Estimated cost',money(m.shopping),'Priced buying suggestions')}${metric('Products to buy',list.filter(s=>s.buy>0).length,'Whole packs rounded up')}${metric('Bring from home',list.filter(s=>s.bring>0).length,'Products available at home')}${metric('Extra requests',state.requests.length,'Clear after purchasing')}</div>`+table(['Item','Category','Unit','Bring from home','Buy packs','Buy quantity','Estimated cost','Supplier','Action'],list.map(s=>`<tr><td class="name">${esc(s.name)}</td><td>${esc(s.category)}</td><td>${esc(s.unit)}</td><td>${qty(s.bring)}</td><td>${qty(s.buy)}</td><td>${qty(BO.numeric(s.buy)?s.buy*s.packSize:null)}</td><td>${money(s.buyCost)}</td><td>${esc(s.supplier)}</td><td>${s.buy>0?action('buy','Record purchase','text-button',s.id):badge(s.status)}</td></tr>`))+`<p class="entry-help">Shopping requests do not increase stock or spending. Extra requests need valid counts and buying levels before they can be included in the automatic estimate.</p><section class="panel"><div class="panel-head"><h2>Extra requests</h2></div>${table(['Item','Extra packs','Notes',''],state.requests.map(r=>`<tr><td>${esc(r.item)}</td><td>${qty(r.packs)}</td><td>${esc(r.notes)}</td><td>${action('remove-request','Clear request','text-button',r.id)}</td></tr>`))}</section>`;}
function receipts(){return heading('Receipts, reconciled.','Register a receipt once. Purchase lines link by receipt ID.',action('add-receipt','+ Add receipt','primary'))+toolsBar()+`<div id="records"></div><p class="entry-help">Difference = entered purchase lines minus printed receipt total. Original source-photo filenames and notes are retained; photos themselves were not embedded in the workbook.</p>`;}
function report(){const ps=state.purchases.map(p=>BO.purchase(p,state)).filter(p=>p.date===state.reportDate),total=BO.sum(ps,p=>p.amount),shop=BO.sum(ps.filter(p=>p.location==='Shop'),p=>p.amount),home=BO.sum(ps.filter(p=>p.location==='Home'),p=>p.amount);return heading('Daily purchase report.',dateText(state.reportDate),`<label class="date-control">Report date<input type="date" id="report-date" value="${state.reportDate}"></label>${action('print','Print report','primary')}`)+`<div class="metrics">${metric('Total spent',money(total),`${ps.length} purchase lines`)}${metric('Kept at shop',money(shop),'Purchases for the shop')}${metric('Kept at home',money(home),'Purchases for home storage')}${metric('Location not recorded',money(total-shop-home),`${ps.filter(p=>p.status!=='Recorded').length} incomplete entries`)}</div>`+table(['Item','Category','Kept at','Packs','Quantity','Unit','Amount paid','Supplier'],ps.map(p=>`<tr><td class="name">${esc(p.item)}</td><td>${esc(p.category)}</td><td>${esc(p.location||'Choose location')}</td><td>${qty(p.packs)}</td><td>${qty(p.quantity)}</td><td>${esc(p.unit)}</td><td class="number">${money(p.amount)}</td><td>${esc(p.supplier)}</td></tr>`))+`<div class="page-total">Daily total: ${money(total)}</div>`;}
function renderRows(){let rows=[],headers=[],markup; if(route==='items'){rows=state.items.filter(match);headers=['ID','Item','Category','Unit','Minimum','Target','Units / pack','Pack price','Supplier',''];markup=i=>`<tr><td>${esc(i.id)}</td><td class="name">${esc(i.name)}</td><td>${esc(i.category)}</td><td>${esc(i.unit)}</td><td>${qty(i.minimum)}</td><td>${qty(i.target)}</td><td>${qty(i.packSize)}</td><td class="money">${money(i.price)}</td><td>${esc(i.supplier)}</td><td>${action('edit-item','Edit','text-button',i.id)}</td></tr>`;}
if(route==='stock'){const ps=state.purchases.map(p=>BO.purchase(p,state));rows=state.items.map(i=>BO.stock(i,state,BO.today(),ps)).filter(match);headers=['Item','Unit','Shop count','Home count','Count date','Current shop','Current home','Total stock','Stock value','Status'];markup=s=>{const c=countDraft[s.id]||state.counts[s.id]||{};return `<tr><td class="name">${esc(s.name)}</td><td>${esc(s.unit)}</td>${s.category==='Fees'?'<td colspan="3">Expense only</td>':`<td class="inline-count"><input aria-label="${esc(s.name)} shop count" type="number" min="0" step="any" data-count="shop" data-id="${esc(s.id)}" value="${esc(c.shop)}"></td><td class="inline-count"><input aria-label="${esc(s.name)} home count" type="number" min="0" step="any" data-count="home" data-id="${esc(s.id)}" value="${esc(c.home)}"></td><td class="inline-count date"><input aria-label="${esc(s.name)} count date" type="date" max="${BO.today()}" data-count="date" data-id="${esc(s.id)}" value="${esc(c.date)}"></td>`}<td>${qty(s.shop)}</td><td>${qty(s.home)}</td><td>${qty(s.total)}</td><td>${money(s.value)}</td><td>${badge(s.status)}</td></tr>`;};}
if(route==='purchases'){rows=state.purchases.map(p=>BO.purchase(p,state)).filter(p=>match(p)&&(!dateFilter||p.date===dateFilter)&&(!statusFilter||(statusFilter==='Recorded'?p.status==='Recorded':p.status!=='Recorded'))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));headers=['Date','Item','Category','Supplier','Quantity','Cost','Kept at','Receipt','Status',''];markup=p=>`<tr><td>${dateText(p.date)}</td><td class="name">${esc(p.item)}</td><td>${esc(p.category)}</td><td>${esc(p.supplier)}</td><td>${esc(p.quantityText||`${qty(p.quantity)} ${p.unit}`)}<br><span class="small">${qty(p.packs)} packs × ${qty(p.size)}</span></td><td class="number money">${money(p.amount)}</td><td>${esc(p.location||'Unallocated')}</td><td>${esc(p.receiptId||'—')} ${p.line!==null?`/ ${p.line}`:''}</td><td>${badge(p.status)}</td><td>${action('edit-purchase','Edit','text-button',p.id)}</td></tr>`;}
if(route==='receipts'){rows=state.receipts.map(r=>BO.receipt(r,state)).filter(r=>!query||Object.values(r).some(v=>String(v).toLowerCase().includes(query.toLowerCase())));headers=['Receipt','Date','Supplier','Printed total','Entered total','Difference','Status','Reference / notes',''];markup=r=>`<tr><td>${esc(r.id)}</td><td>${dateText(r.date)}</td><td>${esc(r.supplier)}</td><td class="number">${money(r.total)}</td><td class="number">${money(r.entered)}</td><td class="number ${r.difference?'error':''}">${money(r.difference)}</td><td>${badge(r.status)}</td><td class="notes">${esc(r.reference)}${r.notes?'<br>'+esc(r.notes):''}</td><td>${action('edit-receipt','Edit','text-button',r.key)}</td></tr>`;}
const p=paginate(rows);$('#records').innerHTML=table(headers,p.slice.map(markup))+p.footer+(route==='purchases'?`<div class="page-total">Filtered total: ${money(BO.sum(rows,p=>p.amount))}</div>`:'');if($('#result-count'))$('#result-count').textContent=`${rows.length} records`;if(route==='receipts')$('#category-filter').hidden=true;}
function guide(){return heading('A straightforward daily routine.','The same workbook logic, with fewer steps.')+`<article class="panel guide"><div class="panel-body"><h2>1. Add receipts and purchases</h2><p>Open Purchases & expenses. Set the date, supplier, storage location and receipt ID once for the batch. Choose an item or type a new one. Existing products fill their category and pack details. Enter the total cost paid for each row, then Save entries.</p><p>Use Paste from Excel for six columns in this order: Date, Item, Category, Supplier, Quantity, Cost. A header row is optional. Review the imported rows before saving.</p><h2>2. Check quantities</h2><p>“Cost” always means the total paid for the row, not a unit price. Details lets you enter packs bought and units per pack. For example, 2 packs × 24 cans adds 48 cans. A description such as “15 kg / 88 box” stays text until you confirm the numeric pack size. The website never guesses an ambiguous quantity.</p><h2>3. Count stock at the end of the day</h2><p>On Stock, enter Shop count, Home count and Count date in amber cells, then Save counts. Enter 0 if none is left. Same-day purchases are already in the count; purchases on later dates are added automatically. Usage and transfers are reflected by your next physical count.</p><h2>4. Let the shopping list calculate</h2><p>Set minimum and target totals in Items. When combined shop and home stock is at or below minimum, the list rounds up the packs needed to reach target. Bring from home uses home stock to fill a shop shortfall. Extra requests are planned buying only; clear them after purchase.</p><h2>5. Reconcile and report</h2><p>Receipts compares printed totals with the linked purchase lines and flags duplicate references, allocations and photos. Spending includes known costs even where quantities or locations need confirming. Daily Report provides a printable date-specific breakdown.</p><h2>6. Save to your GitHub repository</h2><p>The public website can be opened normally without a token. GitHub requires authorization to write records into its repository. Connect your repository in Data & setup and paste a fine-grained token with Contents read and write access for that repository only. Choose Remember this device to reconnect automatically on future visits. Each new device needs one initial authorization.</p><p>Once connected, saved entries automatically commit after a brief pause. A local recovery copy protects unsynced edits. Refresh before working on another device. If two people edit the same version, saving stops with a conflict instead of overwriting the other person’s work. Download your draft backup before refreshing.</p><p>The login is a convenience screen. Initial records, saved repository data and Git history are public. Login credentials do not grant write access to GitHub.</p></div></article>`;}
function dataView(){return heading('Data & setup.','Connect shared saving, import workbooks and keep a backup.')+`<div class="setup-grid"><section class="panel"><div class="panel-head"><h2>GitHub repository</h2></div><div class="panel-body"><p>${repo?`Repository: <strong>${esc(repo.config.owner)}/${esc(repo.config.repo)}</strong>`:'Not connected yet. The preview works before your repository is created.'}</p><p class="small">Records are saved to <code>docs/data/workbook.json</code>. GitHub keeps a version history with each save. New devices read the latest repository data.</p><p class="small">${repo?.token?'Write access connected on this device.':'Write access is not connected. A GitHub token is needed only for repository saves.'}</p><div class="actions">${action('setup','Connect GitHub','primary')}${action('sync','Save to GitHub')}${action('refresh','Refresh from GitHub')}${action('disconnect','Forget GitHub access','text-button')}</div><p class="small">To create the website, upload this project to a repository. In Settings → Pages, choose Deploy from a branch, your main branch and /docs.</p></div></section><section class="panel"><div class="panel-head"><h2>Import & back up</h2></div><div class="panel-body"><p>Import the original Brick & Olive workbook or a JSON backup. Imports replace the current dataset after a preview and confirmation.</p><div class="actions">${action('import','Import Excel / backup')}${action('backup','Download backup','primary')}${action('export','Export Excel')}</div><p class="small">Excel export contains current records and calculated values for reporting. It is a snapshot; use JSON backups to restore this website with full fidelity.</p></div></section></div><div class="notice neutral"><span><strong>Your data is public by choice.</strong> The login does not secure the repository. Tokens are never included in data files, backups or exports.</span></div>`;}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function itemForm(id){const i=state.items.find(i=>i.id===id)||{id:BO.id(),name:'',category:'Food',unit:'each',minimum:null,target:null,packSize:null,price:null,supplier:'',notes:''};modal(id?'Edit item':'Add item',`<form id="item-form" data-id="${esc(i.id)}"><div class="form-grid">${field('name','Item name',i.name,'text','required') }<label>Category<input name="category" value="${esc(i.category)}" list="form-categories" required><datalist id="form-categories">${cats().map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label>${field('unit','Stock unit (each, kg, litre…)',i.unit,'text','required')}${field('supplier','Preferred supplier',i.supplier)}${field('minimum','Minimum total',i.minimum,'number','min="0" step="any"')}${field('target','Target total',i.target,'number','min="0" step="any"')}${field('packSize','Units per pack',i.packSize,'number','min="0.001" step="any"')}${field('price','Pack price (£)',i.price,'number','min="0" step="0.01"')}<label class="wide">Notes<textarea name="notes">${esc(i.notes)}</textarea></label></div><p id="form-error" class="error" role="alert"></p><div class="modal-actions">${id?action('delete-item','Delete item','text-button danger',id):''}${action('close','Cancel')}<button class="primary" type="submit">Save item</button></div></form>`);}
function receiptForm(key){const r=state.receipts.find(r=>r.key===key)||{key:BO.id(),id:nextReceipt(),date:BO.today(),supplier:'',total:null,reference:'',notes:'',photo:'',hash:''};modal(key?'Edit receipt':'Add receipt',`<form id="receipt-form" data-id="${esc(r.key)}"><div class="form-grid">${field('id','Receipt ID',r.id,'text','required')}${field('date','Date',r.date,'date')}${field('supplier','Supplier',r.supplier,'text','required')}${field('total','Printed total (£)',r.total,'number','min="0" step="0.01"')}${field('reference','Receipt reference',r.reference)}${field('photo','Source photo filename',r.photo)}<label class="wide">Notes / confirmation<textarea name="notes">${esc(r.notes)}</textarea></label></div><p id="form-error" class="error"></p><div class="modal-actions">${key?action('delete-receipt','Delete receipt','text-button danger',key):''}${action('close','Cancel')}<button type="submit" class="primary">Save receipt</button></div></form>`);}
function nextReceipt(){let n=Math.max(0,...state.receipts.map(r=>+(r.id.match(/^R(\d+)$/)?.[1]||0)))+1;return 'R'+String(n).padStart(3,'0');}
function details(i){const r=entryRows[i];modal('Purchase line details',`<form id="details-form" data-id="${i}"><p><strong>${esc(r.item||'New purchase')}</strong></p><div class="form-grid">${field('packs','Packs bought',r.packs,'number','min="0.001" step="any" required')}${field('packSize','Units per pack',r.packSize,'number','min="0.001" step="any"')}${field('receiptId','Receipt ID',r.receiptId||batch.receiptId)}${field('line','Original receipt line',r.line,'number','min="1" step="1"')}<label class="wide">Notes<textarea name="notes">${esc(r.notes)}</textarea></label></div><p class="small">Historical pack contents are saved on each purchase. Fractional packs support splitting one receipt line between Shop and Home. Missing size will be flagged for confirmation.</p><div class="modal-actions">${action('close','Cancel')}<button class="primary" type="submit">Apply details</button></div></form>`);}
function parseQuantity(text,item){if(!text.trim())return item?.packSize??null;const s=text.toLowerCase().trim();const n=s.match(/^(\d+(?:\.\d+)?)\s*(each|pieces?|cans?|eggs?|bars?|straws(?:\/box)?|pack|in a box|box)?$/);if(n)return +n[1];const u=s.match(/^(\d+(?:\.\d+)?)\s*(kg|g|litres?|liters?|l|ml)$/);if(u){const value=+u[1],unit=u[2];if(item?.unit==='kg'&&unit==='g')return value/1000;if(item?.unit==='litre'&&unit==='ml')return value/1000;if((item?.unit==='kg'&&unit==='kg')||(item?.unit==='litre'&&['litre','litres','liter','liters','l'].includes(unit)))return value;}return null;}
function editPurchase(id){if(entryRows.some(r=>r.item)&&!confirm('Replace the current unsaved entry rows with this purchase?'))return;const p=BO.purchase(state.purchases.find(p=>p.id===id),state);entryRows=[{...p,packSize:p.size,cost:p.amount??'',quantityText:p.quantityText||`${qty(p.quantity)} ${p.unit}`}];entryEditing=id;batch={...batch,date:p.date,supplier:p.supplier,location:p.location,receiptId:p.receiptId,total:'',reference:''};saveEntryDraft();location.hash='purchases';render();window.scrollTo({top:0,behavior:'smooth'});}
function saveEntries(){const active=entryRows.filter(r=>r.item.trim()||r.cost!==''||r.quantityText.trim());if(!active.length)return flash('Add an item and cost first.');const working=structuredClone(state),saved=[];let nextLine=1;for(const [index,r] of active.entries()){
if(!r.item.trim())return fail(`Row ${index+1}: add an item name.`);if(!BO.validDate(r.date)||r.date>BO.today())return fail(`Row ${index+1}: enter a valid purchase date, not in the future.`);const cost=BO.num(r.cost);if(cost===null||cost<0)return fail(`Row ${index+1}: enter the total cost paid.`);let item=working.items.find(i=>i.name.toLowerCase()===r.item.trim().toLowerCase());if(!item){if(!r.category.trim())return fail(`Row ${index+1}: choose a category for the new item.`);item={id:BO.id(),name:r.item.trim(),category:r.category.trim(),unit:'each',minimum:null,target:null,packSize:BO.num(r.packSize),price:null,supplier:r.supplier.trim(),notes:'Added through purchase entry. Confirm stock unit and buying levels.'};working.items.push(item);}
if(!['Shop','Home'].includes(r.location)&&item.category!=='Fees')return fail(`Row ${index+1}: choose Shop or Home.`);const packs=BO.num(r.packs);if(!(packs>0))return fail(`Row ${index+1}: packs bought must be greater than zero.`);const receiptId=(r.receiptId||batch.receiptId||'').trim();const line=BO.num(r.line)??(receiptId?Math.max(nextLine,...working.purchases.filter(p=>p.receiptId===receiptId).map(p=>(p.line||0)+1)):null);if(line)nextLine=line+1;
const p={id:entryEditing||BO.id(),date:r.date,item:item.name,location:r.location,packs,price:cost/packs,supplier:r.supplier.trim(),receiptId,line,packSize:BO.num(r.packSize)??parseQuantity(r.quantityText,item),quantityText:r.quantityText.trim(),notes:r.notes||''};if(working.purchases.some(q=>q.id!==p.id&&receiptId&&q.receiptId===receiptId&&q.line===line&&q.location===p.location))return fail(`Row ${index+1}: that receipt line already exists at this location. Edit the existing purchase or correct the receipt line.`);
const old=working.purchases.findIndex(q=>q.id===p.id);if(old>=0)working.purchases[old]=p;else working.purchases.push(p);saved.push(p);
if(receiptId&&!working.receipts.some(q=>q.id===receiptId)){working.receipts.push({key:BO.id(),id:receiptId,date:r.date,supplier:p.supplier,total:receiptId===batch.receiptId?BO.num(batch.total):null,reference:receiptId===batch.receiptId?batch.reference.trim():'',notes:'',photo:'',hash:''});}}
state=BO.validate(working);entryEditing=null;entryRows=[blankRow(),blankRow(),blankRow()];saveEntryDraft();changed(`${saved.length} ${saved.length===1?'entry':'entries'} saved`);render();}
function saveCounts(){const entries=Object.entries(countDraft);if(!entries.length)return flash('No counts changed.');for(const [id,c] of entries){if(!BO.numeric(c.shop)||!BO.numeric(c.home)||c.shop<0||c.home<0||!BO.validDate(c.date)||c.date>BO.today())return fail(`For ${state.items.find(i=>i.id===id)?.name}, enter both counts (0 is allowed) and a valid count date.`);}Object.assign(state.counts,countDraft);countDraft={};changed(`${entries.length} stock counts saved`);render();}
function requestForm(){modal('Extra shopping request',`<form id="request-form"><div class="form-grid"><label class="wide">Item<select name="item" required>${options(state.items.filter(i=>i.category!=='Fees').map(i=>i.name),'','Choose an item')}</select></label>${field('packs','Extra packs',1,'number','min="1" step="1" required')}${field('notes','Notes')}</div><div class="modal-actions">${action('close','Cancel')}<button type="submit" class="primary">Add request</button></div></form>`);}
function pasteForm(){modal('Paste from Excel',`<form id="paste-form"><p class="small">Copy six columns: Date, Item, Category, Supplier, Quantity, Cost. Paste below. Header rows are detected. Rows are added to your entry grid for review.</p><textarea name="text" rows="10" placeholder="Paste your copied cells here…" required></textarea><p id="form-error" class="error"></p><div class="modal-actions">${action('close','Cancel')}<button type="submit" class="primary">Add to entry grid</button></div></form>`);}
function setup(){const c=repo?.config||{};modal('Connect GitHub saving',`<form id="setup-form"><p class="small">Create your repository and upload the website first. You can use the preview and keep local drafts until then.</p><div class="form-grid">${field('url','Repository URL',c.owner?`https://github.com/${c.owner}/${c.repo}`:'','url','placeholder="https://github.com/yourname/brick-and-olive" required')}${field('branch','Branch (blank = default)',c.branch||'')}<label class="wide">GitHub access token<input name="token" type="password" autocomplete="off" placeholder="Fine-grained token · Contents: read and write"></label></div><label style="margin-top:1rem"><input type="checkbox" name="remember" checked style="width:auto"> Remember this trusted device</label><p class="small"><a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create a fine-grained token</a> for this repository only, with Contents read and write permission. Remembering saves the token in this browser on this device. It is never put in the repo or backups. Use only on a trusted device. Leave blank for read-only access.</p><p id="form-error" class="error"></p><div class="modal-actions">${action('close','Cancel')}<button type="submit" class="primary">Connect & check</button></div></form>`);}
async function sync(){clearTimeout(syncTimer);if(!repo?.token)return setup();if(!localMeta.dirty)return flash('Already up to date.');if(repo.busy)return;const snapshot=JSON.stringify(state);updateStatus('Saving to GitHub…');try{await repo.write(JSON.parse(snapshot));localMeta.sha=repo.sha;localMeta.dirty=JSON.stringify(state)!==snapshot;persist();updateStatus();flash('Saved to GitHub.');if(localMeta.dirty)syncTimer=setTimeout(()=>sync(),1400);}catch(e){updateStatus('Save failed · local draft safe');flash(e.message);modal('GitHub save needs attention',`<p>${esc(e.message)}</p><p class="small">No local edits were discarded. Download a backup before refreshing to resolve a conflict.</p><div class="modal-actions">${action('backup','Download draft backup')}${action('close','Keep working','primary')}</div>`);}}
async function refresh(auto=false){if(!repo){if(!auto)setup();return;}if(localMeta.dirty){if(auto)return;if(!confirm('Refresh will replace your unsynced workbook changes with GitHub’s version. Download a backup first if you need these changes. Continue?'))return;}const before=JSON.stringify(state);updateStatus('Reading GitHub…');try{const result=await repo.read();if(JSON.stringify(state)!==before)throw Error('You made edits during refresh. They are preserved; save or back them up before refreshing again.');state=result.state;repo.sha=result.sha;localMeta={sha:result.sha,dirty:false};persist();render();if(!auto)flash('Latest records loaded from GitHub.');}catch(e){updateStatus('Refresh failed · showing local copy');if(!auto)fail(e.message);}}
async function importFile(file){try{if(file.size>25*1024*1024)throw Error('Please choose a workbook or backup smaller than 25 MB.');let incoming;if(file.name.toLowerCase().endsWith('.json'))incoming=BO.validate(JSON.parse(await file.text()));else incoming=BO.validate(BO.fromWorkbook(XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),XLSX));const preview=BO.metrics(incoming);window.pendingImport=incoming;modal('Review import',`<p><strong>${esc(file.name)}</strong></p><div class="metrics">${metric('Items',incoming.items.length,'Imported products')}${metric('Purchases',incoming.purchases.length,'Purchase allocations')}${metric('Receipts',incoming.receipts.length,'Registered receipts')}${metric('All spending',money(preview.total),'Known line costs')}</div><p>This replaces the current dataset. Download a backup first. It will then be queued for GitHub saving if connected.</p><div class="modal-actions">${action('backup','Back up current data')}${action('close','Cancel')}${action('confirm-import','Replace current data','primary')}</div>`);}catch(e){fail(e.message);}}
function exportWorkbook(){const m=BO.metrics(state,state.reportDate),wb=XLSX.utils.book_new();const sheet=(name,rows)=>{const s=XLSX.utils.aoa_to_sheet(rows);s['!cols']=rows[0].map(()=>({wch:22}));XLSX.utils.book_append_sheet(wb,s,name);};sheet('Dashboard',[['Metric','Value'],['Summary date',state.reportDate],['Total purchases',m.total],['Selected day',m.day],['Selected week',m.week],['Selected month',m.month],['Stock value',m.value],['Shopping estimate',m.shopping]]);sheet('Items',[['Item ID','Item','Category','Unit','Minimum','Target','Pack size','Pack price','Supplier','Notes'],...state.items.map(i=>[i.id,i.name,i.category,i.unit,i.minimum,i.target,i.packSize,i.price,i.supplier,i.notes])]);sheet('Purchases',[['Date','Item','Category','Supplier','Quantity description','Total cost','Location','Packs','Units per pack','Quantity','Receipt ID','Receipt line','Status','Notes'],...m.ps.map(p=>[p.date,p.item,p.category,p.supplier,p.quantityText,p.amount,p.location,p.packs,p.size,p.quantity,p.receiptId,p.line,p.status,p.notes])]);sheet('Stock',[['Item','Unit','Count date','Shop count','Home count','Current shop','Current home','Total','Value','Status'],...m.stocks.map(s=>[s.name,s.unit,state.counts[s.id]?.date,state.counts[s.id]?.shop,state.counts[s.id]?.home,s.shop,s.home,s.total,s.value,s.status])]);sheet('Shopping',[['Item','Unit','Bring from home','Buy packs','Buy quantity','Estimated cost','Supplier'],...m.stocks.filter(s=>s.buy>0||s.bring>0).map(s=>[s.name,s.unit,s.bring,s.buy,s.buy*s.packSize,s.buyCost,s.supplier])]);sheet('Receipts',[['Receipt ID','Date','Supplier','Printed total','Entered total','Difference','Reference','Status','Notes','Source photo','Photo SHA256'],...state.receipts.map(r=>BO.receipt(r,state,m.ps)).map(r=>[r.id,r.date,r.supplier,r.total,r.entered,r.difference,r.reference,r.status,r.notes,r.photo,r.hash])]);XLSX.writeFile(wb,`Brick-and-Olive-${BO.today()}.xlsx`);flash('Excel snapshot exported. Use JSON backup for restoring the app.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{if(a.startsWith('go-')){location.hash=a.slice(3);return;}switch(a){case 'close':closeModal();break;case 'data':location.hash='data';break;case 'backup':backup();break;case 'export':exportWorkbook();break;case 'print':window.print();break;case 'logout':if(localMeta.dirty&&!confirm('Some changes are not saved to GitHub. Log out and keep the local recovery copy?'))return;sessionStorage.removeItem('bo-login');if(repo)repo.token='';$('#app').hidden=true;$('#login').hidden=false;$('#login-form').reset();break;case 'setup':setup();break;case 'disconnect':localStorage.removeItem(TOKEN);if(repo)repo.token='';flash('GitHub access removed from this device.');render();break;case 'sync':await sync();break;case 'refresh':await refresh();break;case 'import':$('#import-file').click();break;case 'confirm-import':state=window.pendingImport;delete window.pendingImport;countDraft={};closeModal();changed('Workbook imported');render();break;case 'add-item':itemForm();break;case 'edit-item':itemForm(id);break;case 'add-receipt':receiptForm();break;case 'edit-receipt':receiptForm(id);break;case 'edit-purchase':editPurchase(id);break;case 'add-row':entryRows.push(blankRow());renderEntry();$('#entry-body tr:last-child input[data-entry="item"]').focus();break;case 'remove-row':entryRows.splice(+id,1);if(!entryRows.length)entryRows.push(blankRow());renderEntry();break;case 'row-details':details(+id);break;case 'save-entries':saveEntries();break;case 'paste':pasteForm();break;case 'clear-entry':if(entryRows.some(r=>r.item)&&!confirm('Clear these unsaved entry rows?'))return;entryEditing=null;entryRows=[blankRow(),blankRow(),blankRow()];saveEntryDraft();render();break;case 'save-counts':saveCounts();break;case 'request':requestForm();break;case 'remove-request':if(!confirm('Clear this shopping request?'))return;state.requests=state.requests.filter(r=>r.id!==id);changed('Request cleared');render();break;case 'buy':{const i=state.items.find(i=>i.id===id),s=BO.stock(i,state);if(entryRows.some(r=>r.item)&&!confirm('Replace the current entry draft with this shopping purchase?'))return;entryEditing=null;entryRows=[{...blankRow(),item:i.name,category:i.category,supplier:i.supplier,packs:s.buy,packSize:i.packSize,quantityText:`${qty(s.buy*i.packSize)} ${i.unit}`,cost:s.buyCost??''}];saveEntryDraft();location.hash='purchases';render();break;}case 'attention':statusFilter='Needs attention';location.hash='purchases';render();break;case 'clear-filter':query=category=statusFilter=dateFilter='';page=1;render();break;case 'prev':page=Math.max(1,page-1);renderRows();break;case 'next':page++;renderRows();break;case 'delete-item':{const i=state.items.find(i=>i.id===id);if(state.purchases.some(p=>p.item===i.name)||state.requests.some(r=>r.item===i.name))return $('#form-error').textContent='This item has purchases or shopping requests. Keep it to preserve those records.';if(!confirm('Delete this item and its count?'))return;state.items=state.items.filter(i=>i.id!==id);delete state.counts[id];closeModal();changed('Item deleted');render();break;}case 'delete-receipt':{const r=state.receipts.find(r=>r.key===id);if(state.purchases.some(p=>p.receiptId===r.id))return $('#form-error').textContent='This receipt has purchase lines. Edit its details instead.';if(!confirm('Delete this receipt?'))return;state.receipts=state.receipts.filter(r=>r.key!==id);closeModal();changed('Receipt deleted');render();break;}}}catch(err){fail(err.message);}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){query=t.value;page=1;renderRows();}if(t.dataset.entry){const r=entryRows[+t.closest('tr').dataset.row];r[t.dataset.entry]=t.value;$('#entry-total').textContent=money(entryTotal());saveEntryDraft();}if(t.dataset.batch){const k=t.dataset.batch,old=batch[k];batch[k]=t.value;entryRows.forEach(r=>{if(k in r&&(r[k]===old||!r[k]))r[k]=t.value;});saveEntryDraft();}if(t.dataset.count){const id=t.dataset.id;countDraft[id]??={...(state.counts[id]||{shop:null,home:null,date:BO.today(),notes:''})};countDraft[id][t.dataset.count]=t.dataset.count==='date'?t.value:BO.num(t.value);}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='category-filter'){category=t.value;page=1;renderRows();}if(t.id==='status-filter'){statusFilter=t.value;page=1;renderRows();}if(t.id==='date-filter'){dateFilter=t.value;page=1;renderRows();}if(t.id==='report-date'&&BO.validDate(t.value)){state.reportDate=t.value;changed('Summary date updated');render();}if(t.dataset.batch)renderEntry();if(t.dataset.entry){const r=entryRows[+t.closest('tr').dataset.row];if(t.dataset.entry==='item'){const item=state.items.find(i=>i.name.toLowerCase()===t.value.toLowerCase());if(item){r.item=item.name;r.category=item.category;r.supplier=r.supplier||item.supplier;r.packSize=item.packSize;r.quantityText=item.packSize?`${qty(item.packSize)} ${item.unit}`:'';r.cost=item.price??'';r.packs=1;renderEntry();}}if(t.dataset.entry==='quantityText'){r.packSize=parseQuantity(r.quantityText,state.items.find(i=>i.name===r.item));r.packs=1;saveEntryDraft();}}if(t.id==='import-file'&&t.files[0]){importFile(t.files[0]);t.value='';}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='login-form'){e.preventDefault();if(f.username.value==='mokabrew'&&f.password.value==='brickandolive'){sessionStorage.setItem('bo-login','yes');if(repo&&!repo.token)repo.token=localStorage.getItem(TOKEN)||'';$('#login').hidden=true;$('#app').hidden=false;if(state)render();else $('#main').innerHTML='<p>Loading workbook…</p>';}else $('#login-error').textContent='Username or password is incorrect.';return;}if(!['item-form','receipt-form','details-form','request-form','paste-form','setup-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));try{if(f.id==='item-form'){data.name=data.name.trim();data.category=data.category.trim();if(!data.name||!data.category)throw Error('Enter an item name and category.');if(state.items.some(i=>i.id!==f.dataset.id&&i.name.toLowerCase()===data.name.toLowerCase()))throw Error('An item with this name already exists.');['minimum','target','packSize','price'].forEach(k=>data[k]=BO.num(data[k]));if(data.target!==null&&data.minimum!==null&&data.target<data.minimum)throw Error('Target must be at least the minimum.');const old=state.items.find(i=>i.id===f.dataset.id);if(old){if(old.name!==data.name){state.purchases.forEach(p=>{if(p.item===old.name)p.item=data.name;});state.requests.forEach(r=>{if(r.item===old.name)r.item=data.name;});}Object.assign(old,data);}else state.items.push({id:f.dataset.id,...data});closeModal();changed('Item saved');render();}
if(f.id==='receipt-form'){data.id=data.id.trim();if(!data.id)throw Error('Enter a receipt ID.');if(state.receipts.some(r=>r.key!==f.dataset.id&&r.id===data.id))throw Error('This receipt ID already exists.');const old=state.receipts.find(r=>r.key===f.dataset.id);data.total=BO.num(data.total);if(old){if(old.id!==data.id)state.purchases.forEach(p=>{if(p.receiptId===old.id)p.receiptId=data.id;});Object.assign(old,data);}else state.receipts.push({key:f.dataset.id,hash:'',...data});closeModal();changed('Receipt saved');render();}
if(f.id==='details-form'){['packs','packSize','line'].forEach(k=>data[k]=BO.num(data[k]));Object.assign(entryRows[+f.dataset.id],data);closeModal();renderEntry();}
if(f.id==='request-form'){state.requests.push({id:BO.id(),item:data.item,packs:+data.packs,notes:data.notes});closeModal();changed('Request added');render();}
if(f.id==='paste-form'){const lines=data.text.trim().split(/\r?\n/),added=[];for(let n=0;n<lines.length;n++){if(!lines[n].trim())continue;const c=lines[n].split('\t');if(n===0&&/^date$/i.test(c[0].trim()))continue;if(c.length<6)throw Error(`Line ${n+1}: expected six tab-separated columns.`);const d=BO.parseDate(c[0].trim());if(!BO.validDate(d))throw Error(`Line ${n+1}: use DD/MM/YYYY dates.`);const cost=BO.num(c[5].replace(/[£,\s]/g,''));if(cost===null||cost<0)throw Error(`Line ${n+1}: check cost.`);const item=state.items.find(i=>i.name.toLowerCase()===c[1].trim().toLowerCase());added.push({...blankRow(),date:d,item:item?.name||c[1].trim(),category:c[2].trim()||item?.category||'',supplier:c[3].trim(),quantityText:c[4].trim(),cost,packSize:parseQuantity(c[4],item)});}if(!added.length)throw Error('No data rows found.');if(entryEditing)throw Error('Finish or cancel your single-row edit before pasting a batch.');entryRows=entryRows.filter(r=>r.item||r.cost!=='').concat(added);closeModal();renderEntry();}
if(f.id==='setup-form'){const match=data.url.match(/^https:\/\/github\.com\/([\w.-]+)\/([\w.-]+)\/?$/);if(!match)throw Error('Enter a GitHub repository URL such as https://github.com/name/repository.');const config={owner:match[1],repo:match[2].replace(/\.git$/,''),branch:data.branch.trim()};const next=new BORepository(config);next.token=data.token.trim();const btn=f.querySelector('[type=submit]');btn.disabled=true;btn.textContent='Checking…';try{const remote=await next.read();const sameRepo=repo&&JSON.stringify(repo.config)===JSON.stringify(config);if(localMeta.dirty&&localMeta.sha&&sameRepo&&localMeta.sha!==remote.sha)throw Error('GitHub has newer changes. Back up your local draft, then refresh before connecting write access.');if(localMeta.dirty&&!(sameRepo&&localMeta.sha===remote.sha)&&!confirm('Keep your local draft as the next version of this repository? It will replace the current GitHub dataset when you save. Cancel to leave setup unchanged.')){btn.disabled=false;btn.textContent='Connect & check';return;}repo=next;repo.sha=remote.sha;localMeta.sha=remote.sha;if(!localMeta.dirty)state=remote.state;localStorage.setItem(CFG,JSON.stringify(config));if(data.remember==='on'&&next.token)localStorage.setItem(TOKEN,next.token);else localStorage.removeItem(TOKEN);persist();closeModal();render();flash(repo.token?'GitHub connected. Save to GitHub to upload your pending changes.':'GitHub connected for reading.');}catch(err){btn.disabled=false;btn.textContent='Connect & check';throw err;}}
}catch(err){const el=f.querySelector('#form-error');if(el)el.textContent=err.message;else flash(err.message);}});
$('#show-password').addEventListener('click',()=>{const p=$('#login-form input[name=password]');p.type=p.type==='password'?'text':'password';$('#show-password').textContent=p.type==='password'?'Show':'Hide';});
window.addEventListener('hashchange',()=>{query=category=dateFilter='';page=1;render();});
window.addEventListener('beforeunload',e=>{if(localMeta.dirty||Object.keys(countDraft).length||entryRows.some(r=>r.item)){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===KEY)flash('Another tab changed the workbook. Back up your work, then reload before continuing.');});
(async function boot(){try{const saved=localStorage.getItem(KEY);if(saved){try{const parsed=JSON.parse(saved);state=BO.validate(parsed.state);localMeta={sha:parsed.sha||null,dirty:!!parsed.dirty};}catch{bootError='Stored recovery data could not be read. It has not been overwritten.';throw Error(bootError);}}
const response=await fetch('./data/workbook.json',{cache:'no-store'});if(!response.ok)throw Error('Could not load the initial workbook.');initial=BO.validate(await response.json());state??=structuredClone(initial);const cfg=localStorage.getItem(CFG);if(cfg){repo=new BORepository(JSON.parse(cfg));repo.sha=localMeta.sha;repo.token=localStorage.getItem(TOKEN)||'';}else if(location.hostname.endsWith('.github.io')){const owner=location.hostname.split('.')[0],name=location.pathname.split('/').filter(Boolean)[0]||`${owner}.github.io`;repo=new BORepository({owner,repo:name,branch:''});}readDraft();render();if(sessionStorage.getItem('bo-login')==='yes'){$('#login').hidden=true;$('#app').hidden=false;}if(repo)await refresh(true);}catch(e){if(state){readDraft();render();flash('Using local recovery data. Initial file is unavailable.');}else{$('#login-error').textContent=e.message;$('#main').innerHTML=`<div class="notice error">${esc(e.message)} Open via a local server or GitHub Pages and check that data/workbook.json is present.</div>`;}}})();
